public:
 using Kind=T::Kind;using Child=T::Child;
 explicit ControllerMidiNoteRuntime(Kind k,uint32_t payload):note_(k),payload_(payload){}
 bool complete()const{return note_.complete();}bool awaitingChild()const{return note_.awaitingChild()&&!helper_&&!nearest_&&(!release_||release_->awaitingChild())&&!heldOff_&&(!heldOn_||heldOn_->awaitingFirstNote())&&(!trigger_||trigger_->awaitingDspTail()||(voiceBuild_&&voiceBuild_->awaitingChild()&&(!selection_||selection_->complete())&&(!activation_||activation_->awaitingDsp())));}Child child()const{return note_.child();}uint8_t note()const{return note_.offPath()&&note_.awaitingChild()&&note_.child()==Child::Trigger?note_.previousNote():note_.note();}uint8_t velocity()const{return note_.offPath()&&note_.awaitingChild()&&note_.child()==Child::Trigger?note_.previousVelocity():note_.velocity();}bool offPath()const{return note_.offPath();}bool awaitingVoiceRelease()const{return release_&&release_->awaitingChild();}MidiVoiceReleaseTask::Child releaseChild()const{return release_?release_->child():MidiVoiceReleaseTask::Child::VoiceAddress;}uint32_t releaseVoice()const{return release_?release_->voice():0;}bool releaseDspWrite()const{return release_&&release_->dspWrite();}uint16_t releaseDspAddress()const{return release_?release_->dspAddress():0;}bool resumeVoiceRelease(MidiVoiceReleaseTask::Child c){return release_&&release_->resume(c);}bool awaitingStartVoice()const{return voiceBuild_&&voiceBuild_->awaitingChild()&&(!selection_||selection_->complete())&&(!activation_||activation_->awaitingDsp());}bool awaitingActivationDsp()const{return activation_&&activation_->awaitingDsp();}VoiceActivationTask::Child activationChild()const{return activation_?activation_->child():VoiceActivationTask::Child::None;}uint32_t activationVoice()const{return activation_?activation_->voice():0;}uint16_t activationDspAddress()const{return activation_?activation_->dspAddress():0;}bool resumeActivationDsp(VoiceActivationTask::Child c,uint16_t command){return activation_&&activation_->resumeDsp(c,command);}bool allocationSelected()const{return selection_&&selection_->complete();}uint8_t selectedVoice()const{return selection_?selection_->slot():0;}uint8_t voiceAllocation()const{return selection_?selection_->allocation():0;}MidiVoiceBuildTask::Child voiceBuildChild()const{return voiceBuild_->child();}bool awaitingBuildDsp()const{return voiceBuild_&&voiceBuild_->awaitingDsp();}bool buildDspSetAddress()const{return voiceBuild_&&voiceBuild_->dspSetAddress();}uint16_t buildDspAddress()const{return voiceBuild_?voiceBuild_->dspAddress():0;}uint16_t voiceCommand()const{return voiceBuild_?voiceBuild_->command():0;}uint32_t voiceWord()const{return voiceBuild_?voiceBuild_->word():0;}bool tailVoiceBuild()const{return voiceStart_&&voiceStart_->tailBuild();}uint32_t voicePatch()const{return voiceStart_?voiceStart_->patch():0;}uint32_t voicePartAddress()const{return voiceStart_?voiceStart_->partAddress():0;}bool awaitingTriggerDsp()const{return trigger_&&trigger_->awaitingDspTail();}uint8_t triggerValue()const{return awaitingTriggerDsp()?trigger_->triggerValue():0;}bool resumeVoiceBuild(MidiVoiceBuildTask::Child c,uint32_t word){if(!awaitingStartVoice()||!voiceBuild_->resume(c,word))return false;if(c==MidiVoiceBuildTask::Child::Allocate)selection_.reset();if(voiceBuild_->complete()){voiceBuild_.reset();if(!voiceStart_->resumeBuild())return false;if(voiceStart_->complete()){voiceStart_.reset();return trigger_->resumeVoice();}}return true;}bool resumeTriggerDsp(){if(!awaitingTriggerDsp()||!trigger_->resumeDspTail())return false;trigger_.reset();return note_.resume(Child::Trigger);}bool awaitingFirstNote()const{return heldOn_&&heldOn_->awaitingFirstNote();}bool resumeFirstNote(){return awaitingFirstNote()&&heldOn_->resumeFirstNote();}
